          <input type="text" id="em_name" placeholder="Enter your full name" required style="width: 100%; padding: 12px 14px; border-radius: 12px; border: 1.5px solid #E2E8F0; font-size: 14px; color: #0F172A; background: #F8FAFC; outline: none; box-sizing: border-box;">
        </div>
        <div class="form-group-custom" style="display: flex; flex-direction: column; gap: 6px; text-align: left;">
          <label for="em_phone" style="font-size: 12px; font-weight: 700; color: #334155; text-transform: uppercase; letter-spacing: 0.5px; font-family: 'Inter', sans-serif;">Mobile Number <span style="color:#d9251d;">*</span></label>
          <input type="tel" id="em_phone" placeholder="Enter 10-digit mobile number" required pattern="[0-9]{10}" style="width: 100%; padding: 12px 14px; border-radius: 12px; border: 1.5px solid #E2E8F0; font-size: 14px; color: #0F172A; background: #F8FAFC; outline: none; box-sizing: border-box;">
        </div>
        <div class="form-group-custom" style="display: flex; flex-direction: column; gap: 6px; text-align: left;">
          <label for="em_email" style="font-size: 12px; font-weight: 700; color: #334155; text-transform: uppercase; letter-spacing: 0.5px; font-family: 'Inter', sans-serif;">Your Email <span style="font-size:10px; color:#64748B; font-weight:500;">(Optional)</span></label>
          <input type="email" id="em_email" placeholder="Enter your email address (Optional)" style="width: 100%; padding: 12px 14px; border-radius: 12px; border: 1.5px solid #E2E8F0; font-size: 14px; color: #0F172A; background: #F8FAFC; outline: none; box-sizing: border-box;">
        </div>
        <div class="form-group-custom" style="display: flex; flex-direction: column; gap: 6px; text-align: left;">
          <label for="em_message" style="font-size: 12px; font-weight: 700; color: #334155; text-transform: uppercase; letter-spacing: 0.5px; font-family: 'Inter', sans-serif;">Message / Requirements <span style="color:#d9251d;">*</span></label>
          <textarea id="em_message" rows="3" placeholder="Describe your product requirements or project specifications..." required style="width: 100%; padding: 12px 14px; border-radius: 12px; border: 1.5px solid #E2E8F0; font-size: 14px; color: #0F172A; background: #F8FAFC; outline: none; box-sizing: border-box; resize: vertical;"></textarea>
        </div>
        <button type="submit" class="email-submit-btn" style="margin-top: 6px; width: 100%; padding: 14px 20px; border-radius: 12px; border: none; background: linear-gradient(135deg, #D9251D 0%, #8F140F 100%); color: #ffffff; font-size: 15px; font-weight: 700; display: flex; align-items: center; justify-content: center; gap: 10px; cursor: pointer; box-shadow: 0 8px 20px rgba(217, 37, 29, 0.35);">
          <i class="fas fa-paper-plane" style="font-size: 16px;"></i>
          <span>Send Inquiry Email</span>
        </button>
      </form>
    </div>
  </div>

  <script src="assets/js/script.js"></script>
  <script>
    function toggleWhatsAppModal(show) {
      const waModal = document.getElementById('whatsappModal');
      if (waModal) {
        if (show) {
          waModal.classList.add('active');
          waModal.style.display = 'flex';
        } else {
          waModal.classList.remove('active');
          waModal.style.display = 'none';
        }
      }
    }
    function toggleEmailModal(show) {
      const emModal = document.getElementById('emailModal');
      if (emModal) {
        if (show) {
          emModal.classList.add('active');
          emModal.style.display = 'flex';
        } else {
          emModal.classList.remove('active');
          emModal.style.display = 'none';
        }
      }
    }
    document.addEventListener('DOMContentLoaded', function() {
      const waForm = document.getElementById('whatsappForm');
      const waModal = document.getElementById('whatsappModal');
      const emForm = document.getElementById('emailForm');
      const emModal = document.getElementById('emailModal');
      const hamburger = document.getElementById('hamburger');
      const mobileMenu = document.getElementById('mobile-menu');

      if (waModal) {
        waModal.addEventListener('click', function(e) {
          if (e.target === waModal) toggleWhatsAppModal(false);
        });
      }
      if (emModal) {
        emModal.addEventListener('click', function(e) {
          if (e.target === emModal) toggleEmailModal(false);
        });
      }
      if (waForm) {
        waForm.addEventListener('submit', function(e) {
          e.preventDefault();
          const name = document.getElementById('wa_name').value.trim();
          const phone = document.getElementById('wa_phone').value.trim();
          const email = document.getElementById('wa_email').value.trim();
          const msg = document.getElementById('wa_message').value.trim();
          let text = `*New WhatsApp Inquiry - Fan Air India*\n\n*Name:* ${name}\n*Phone:* ${phone}\n`;
          if (email) text += `*Email:* ${email}\n`;
          text += `*Requirement:* ${msg}`;
          window.open(`https://wa.me/919811347199?text=${encodeURIComponent(text)}`, '_blank');
          toggleWhatsAppModal(false);
          waForm.reset();
        });
      }
      if (emForm) {
        emForm.addEventListener('submit', function(e) {
          e.preventDefault();
          const name = document.getElementById('em_name').value.trim();
          const phone = document.getElementById('em_phone').value.trim();
          const email = document.getElementById('em_email').value.trim();
          const msg = document.getElementById('em_message').value.trim();
          let bodyText = `Name: ${name}\nPhone: ${phone}\nEmail: ${email}\n\nRequirement:\n${msg}`;
          window.location.href = `mailto:saurabh.joshi@fanair.in?subject=${encodeURIComponent('Product Inquiry - Fan Air India')}&body=${encodeURIComponent(bodyText)}`;
          toggleEmailModal(false);
          emForm.reset();
        });
      }
    });
  </script>
</body>
</html>
